-- Triax vessels from printed pages 071-105.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzz-triax-vessels-p071-105.sql
--
-- BOOK-INGEST-AUDIT.md F3. The vessels were excluded from every batch of
-- this book because `gear` holds one mdc, one damage, one range and one
-- payload, and a vessel here has M.D.C. by LOCATION and several numbered
-- weapon systems with four stats each. Migration 048 gave them three tables
-- of their own - vehicles, vehicle_locations, vehicle_weapons - and this is
-- the data that was waiting on them.
--
-- A VESSEL BELONGS TO THE SLICE ITS NAME HEADING FALLS IN. That rule is why
-- no vessel is split across two of these files and none is imported twice:
-- a reader whose stat block runs past a page boundary read on to finish it,
-- and a reader who met a block already in progress skipped it.
--
-- INSERT OR IGNORE THROUGHOUT, and the readbacks COUNT rather than trusting
-- the exit code - an IGNORE that collides is silent, which is exactly how a
-- row goes missing without an error.
--
-- mdc_main_body is the main body ONLY. The full printed block is in
-- vehicle_locations, main body included, so it can be rendered in the order
-- the book sets it; a reader wanting a total must sum the rows.
--
-- A LOCATION WHOSE M.D.C. THE BOOK PRINTS AS A FORMULA carries mdc NULL and
-- the formula in mdc_note. The EIR-50 Gurgoyle Android is the whole reason:
-- its block is printed as dice, not numbers, because the machine is built to
-- match whatever gurgoyle it is imitating.

INSERT OR IGNORE INTO vehicles
  (slug, name, system, vehicle_class, crew, passengers, speed_ground,
   speed_air, speed_water, dimensions, weight_tons, mdc_main_body, cost,
   cost_note, description, source_book)
VALUES
('x-2500-black-knight', 'X-2500 Black Knight', 'rifts', 'robot', 'Two: One pilot and a co-pilot/gunner.', 'Four human-size passengers can also be accommodated.', 'Running: 70 mph (112.6 km) maximum. Cruising speed usually around 40 mph (64 km). Well suited for most terrains including underwater; reasonably good climbing mountains, cannot climb sheer walls.', 'Flying: Not possible. Leaping: 20 feet (6 m) high/lengthwise from stationary; 30 feet (9 m) high or 40 feet (13.7 m) lengthwise from a running start.', NULL, 'Height: 35 feet (10.7 m) from bottom of feet to top of sensor head; antenna adds another four feet (1.2 m). Width: 23 feet (6.9 m) shoulder to shoulder. Length: 9 feet (2.7 m)', '30 tons', 750, 45000000, '45 million credits for an undamaged unit with all weapon systems intact (Black Market Cost)', 'One of the NGR''s largest robot vehicles at 35 feet tall, a ground infantry assault robot armed with an ion cannon, electro-mace, forearm lasers and vibro-swords, leg missile launchers and grenade tubes, used to take on the largest monsters and enemy robots.', 'Rifts World Book 5: Triax and the NGR p.73-74'),
('x-2700-dragonwing', 'X-2700 Dragonwing', 'rifts', 'robot', 'One pilot and typically a co-pilot/gunner.', 'Two human-size passengers can also be accommodated.', 'Running: 40 mph (64 km) maximum. Cruising speed usually around 25 mph (40 km). Suited for most terrains including outer space and underwater.', 'Full hover and evasive flight; cruise 1 to 300 mph (1.6-482.7 km) up to Mach 2 (approx 1340 mph/2144 km). Altitude as high as 45,000 feet (13,716 m) and as low as five feet (1.5 m). Leaping: 10 feet (3 m) high/lengthwise from stationary; Jet Assisted Leaps: 100 feet (30.5 m) high or lengthwise without flying.', 'Underwater: Maximum speed of 50 mph (80 km). Maximum depth of 600 feet (183 m).', 'Height: 30 feet (9.1 m) from bottom of feet to top of back; antenna adds another 10 feet (3 m). Width: 16 feet (4.9 m) shoulder to shoulder. Length: 27 feet (8.2 m)', '28 tons', 525, 45000000, '45 million credits for an undamaged unit with all weapon systems intact (Black Market Cost)', 'The only giant NGR infantry robot capable of true flight, reaching Mach 2 and using radar-reflective paint to remain largely invisible to radar; used for aerial combat against gargoyles and flying monsters, escort, extraction and deep reconnaissance.', 'Rifts World Book 5: Triax and the NGR p.75-78'),
('x-5000-devastator', 'X-5000 Devastator', 'rifts', 'robot', 'Two: One pilot and a co-pilot/gunner. A communications officer and/or intelligence officer is optional.', 'The giant bot can accommodate as many as six additional human-size passengers comfortably and contains four man-size suits of body armor as part of its armaments; typically the T-31 Super Trooper or X-10A Predator, or basic X-535 Jager.', 'Running: 40 mph (64 km) maximum. Cruising speed usually around 20 mph (32 km). Suitable for most terrains including outer space and underwater.', 'Leaping: Not possible. Flying: Not possible.', NULL, 'Height: 50 feet (15.2 m) from bottom of feet to top of sensor head; ion cannon adds another 20 feet (6 m) when stowed upward. Width: 30 feet (9 m) shoulder to shoulder. Length: 25 feet (7.6 m)', '150 tons', 1500, 150000000, '150 million credits! (Black Market Cost)', 'The largest infantry robot Triax has ever created, standing 50 feet tall as a walking artillery platform with two long-range cannons and over a hundred missiles, serving as the cornerstone of mobile assault forces despite slow speed and vulnerability to fast, close-in opponents.', 'Rifts World Book 5: Triax and the NGR p.79-81'),
('dv-12-dyna-bot', 'DV-12 Dyna-Bot', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Running: 120 mph (192 km) maximum. Running does NOT tire the robot; speed maintained indefinitely.', 'None, without the addition of a T-100 Eagle jet pack. Leaping: limited to approximately 12 feet (3.7 m) high or lengthwise; running leap at 60+ mph (96 km) adds 2D6+6 yards/meters.', NULL, 'Height: 7 feet, 4 inches (2.2 m). Width: 3 feet (0.9 m). Length: 3 feet (0.9 m)', '500 lbs (225 kg)', 130, 3000000, 'Black market sells the bots for three million credits new and undamaged, complete with combat program, assault rifle and bot weapon systems; Very poor availability. Combat version without weapons/programming costs two and a half million credits. A bootleg DV-12 combat program costs 500,000 credits.', 'An expendable, artificial-intelligence-driven man-sized assault robot used by the NGR as laborers, guards, infantry troops and hunter/killers, especially against gargoyles and other Monster Zone enemies; convertible between labor and combat programming in under a minute.', 'Rifts World Book 5: Triax and the NGR p.82-84'),
('dv-15-sentry-bot', 'DV-15 Sentry-Bot', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Running: 100 mph (160 km) maximum. Running does NOT tire the robot; speed maintained indefinitely.', 'None, without the addition of a T-100 Eagle jet pack. Leaping: limited to approximately 12 feet (3.7 m) high or lengthwise; running leap at 60+ mph (96 km) adds 2D6+6 yards/meters.', NULL, 'Height: 8 feet (2.4 m). Width: 3 feet (0.9 m). Length: 3 feet (0.9 m)', '650 lbs (292.5 kg)', 160, 3000000, 'Black market sells the bots for three million credits, new and undamaged; Sentry-bots have not been sold overseas in the Americas.', 'A heavier-armored modification of the DV-12 Dyna-bot with a multi-sensor crown, used by the NGR military mainly as tireless, incorruptible guards and defenders for prisoners, bases, and strategic locations.', 'Rifts World Book 5: Triax and the NGR p.84-86'),
('dv-40-hunter-killer-drone', 'DV-40 Hunter/Killer Drone', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Running: 70 mph (112 km) maximum. Running does NOT tire the robot; speed maintained indefinitely.', 'None, without the addition of a T-100 Eagle jet pack. Leaping: approximately 25 feet (7.6 m) high or lengthwise; running leap at 50+ mph (80 km) adds 2D6+6 yards/meters.', NULL, 'Height: 13 feet (3.9 m). Width: 7 feet (2.1 m). Length: 4 feet, 5 inches (1.35 m)', 'One ton', 300, 10000000, 'Black market sells the DV-40 for 10 million credits, new and undamaged. Poor availability.', 'A larger, giant-sized hunter/killer robot drone used to defoliate forests, destroy enemy strongholds, and conduct special-forces-style tactical assaults, typically sent in groups of three, sometimes accompanied by DV-12 Dyna-bots.', 'Rifts World Book 5: Triax and the NGR p.87-90'),
('eir-10-gargoyle-drone', 'EIR-10 Gargoyle Drone', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Running: 40 mph (64 km) maximum, faster than most real gargoyles (15-35 mph/24-56 km). Running does NOT tire the robot; speed maintained indefinitely.', 'Flying/Gliding: Limited. Maximum speed 40 mph (64 km); maximum height 500 feet (153 m); flight maintained up to 15 minutes before losing altitude. Leaping: normal leap 20 feet (6 m) high/lengthwise; running leap adds 1D6+6 yards/meters; jet thruster assisted leaps up to 80 feet (24.4 m) high/lengthwise.', NULL, 'Height: 15 feet (4.6 m). Width: Body 6 feet (1.8 m), wing span 25 feet (7.6 m). Length: Body 4 feet (1.2 m); tail an additional 10-15 feet (3-4.6 m) long.', '2000 lbs (900 kg)', 250, NULL, 'Not available; unknown to the black market. Estimated value is 10 million credits.', 'An Enemy Infiltration Robot (EIR) sculpted and skinned to impersonate a winged gargoyle, used by the NGR as a spy and assassin behind enemy lines; capable of only limited flight/gliding compared to a real gargoyle, and self-destructs when destroyed to avoid capture.', 'Rifts World Book 5: Triax and the NGR p.91-92'),
('eir-15-gargoyle-manned-robot', 'EIR-15 Gargoyle Manned Robot', 'rifts', 'robot', 'One human pilot - typically commando or intelligence.', NULL, 'Running: 40 mph (64 km) maximum, faster than most real gargoyles (15-35 mph/24-56 km). Running does NOT tire the robot or pilot; speed maintained indefinitely.', 'Flying/Gliding: Limited. Maximum speed 40 mph (64 km); maximum height 500 feet (153 m); flight maintained up to 15 minutes. Leaping: normal leap 20 feet (6 m) high/lengthwise; running leap adds 1D6+6 yards/meters; jet thruster assisted leaps up to 80 feet (24.4 m) high/lengthwise.', NULL, 'Height: 20 feet (6 m). Width: Body 8 feet (2.4 m), wing span 30 feet (9 m). Length: Body 6 feet (1.8 m); tail an additional 10-15 feet (3-4.6 m) long.', '3000 lbs (1350 kg)', 280, NULL, 'Not available; unknown to the black market. Estimated value is 10 million credits.', 'A larger, human-piloted version of the EIR-10 gargoyle infiltration robot reserved for commandos and intelligence officers, letting a human pilot infiltrate as a living gargoyle for deep espionage and exploration of Monster Zones.', 'Rifts World Book 5: Triax and the NGR p.93-94'),
('eir-20-gurgoyle-drone', 'EIR-20 Gurgoyle Drone', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Running: 50 mph (80 km) maximum, faster than most real gurgoyles (15-35 mph/24-56 km). Running does NOT tire the robot; speed maintained indefinitely.', 'Flying: Not applicable. Leaping: normal leap 20 feet (6 m) high/lengthwise; running leap adds 1D6+6 yards/meters.', NULL, 'Height: 10 feet (3 m). Width: 4 feet (1.2 m). Length: 3 feet (0.9 m); tail an additional 8 feet (2.4 m) long.', '1000 lbs (450 kg)', 200, NULL, 'Not available; unknown to the black market. Estimated value is 8 million credits.', 'The smaller, wingless gurgoyle version of the Enemy Infiltration Robot, used by the NGR as a spy and assassin to infiltrate enemy forces, perform reconnaissance, and ferret out gargoyle sympathizers and bandits.', 'Rifts World Book 5: Triax and the NGR p.94-95'),
('eir-30-gargoylite-drone', 'EIR-30 Gargoylite Drone', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Running: 10 mph (16 km) maximum.', 'Flying: concealed thrusters (beneath wings/tail/feet) give maximum speed 120 mph (192 km), maximum height 5000 feet (1530 m); flight maintained indefinitely. Leaping: normal leap 5 feet (1.5 m) high/lengthwise; running leap adds 1D6 feet; jet thruster assisted leaps up to 80 feet (24.4 m) high/lengthwise.', NULL, 'Height: 3 feet (0.9 m). Width: 1 foot, 5 inches (0.35 m). Length: 1 foot, 5 inches (0.35 m); stubby tail adds another 1 foot (0.3 m).', '100 lbs (45 kg)', 50, NULL, 'Not available; unknown to the black market. Estimated value is 10 million credits.', 'A small, inexpensive reconnaissance and surveillance drone built to resemble the diminutive gargolyite, used for spying, theft, sabotage and smuggling out prisoners and information; can zoom away on concealed thrusters if suspected of being an EIR.', 'Rifts World Book 5: Triax and the NGR p.95-96'),
('eir-50-gurgoyle-android', 'EIR-50 Gurgoyle Android', 'rifts', 'drone', 'None; artificial intelligence', NULL, 'Average Speed Running: 22.5 mph (36 km); a speed attribute of 33. Effectively the same as a living gurgoyle.', NULL, NULL, 'Average Height: Typically 10 feet (3 m) tall, but can range from 8 to 12 feet (2.4-3.6 m). (Statistical Data otherwise effectively the same as a living gurgoyle.)', '1300 lbs (585 kg)', NULL, NULL, 'Not available; unknown to the black market. Estimated value unknown.', 'An experimental organic robot: the living brain of a recently deceased gurgoyle replaced with a robot brain controlling the mega-damage flesh-and-blood body, giving a near-undetectable infiltrator intended to eventually replace the EIC-100 gurgoyle cyborg.', 'Rifts World Book 5: Triax and the NGR p.96-97'),
('eic-100-gurgoyle-cyborg', 'EIC-100 Gurgoyle Cyborg', 'rifts', 'borg', 'One human volunteer - typically with a background in intelligence.', NULL, 'Running: 90 mph (144 km) maximum; roughly two and a half times faster than most real gurgoyles. Cyborgs fatigue at one-third the rate of a normal human.', 'Flying: Via jet pack only. Leaping: 20 feet (6 m) high/lengthwise; running leap adds 1D6+6 yards/meters.', NULL, 'Average Height: 9 feet (2.7 m). Width: 3 feet, 6 inches (1 m). Length: 3 feet (0.9 m); tail an additional 8 feet (2.4 m) long.', '1200 lbs (540 kg)', 250, NULL, 'Not available; unknown to the black market. Estimated value is two million credits.', 'The NGR''s best infiltration operative: a full-conversion cyborg housed in a gurgoyle-shaped bionic body with cosmetic artificial skin, giving human judgment, emotion and improvisation the robot EIR drones lack, used for reconnaissance, intelligence, sabotage and assassination.', 'Rifts World Book 5: Triax and the NGR p.97-99'),
('vx-300-striker', 'VX-300 Striker', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 120 mph (192 km) maximum.', 'Flying: Via jet pack only. Leaping: 20 feet (6 m) high/lengthwise; running leap adds 30 additional feet (9 m).', NULL, 'Average Height: 7 feet, 6 inches (2.2 m). Width: 3 feet, 6 inches (1 m). Length: 2 feet, 6 inches (0.7 m).', '600 lbs (270 kg)', 180, 2000000, 'Two to four million credits with all standard features and weapons. Poor availability.', 'A light assault cyborg for reconnaissance, guerrilla warfare and seek-and-destroy missions, roughly human size with a removable armored helmet, gauntlet and missile plate that reveal the pilot''s human face and hand.', 'Rifts World Book 5: Triax and the NGR p.99-101'),
('vx-320-cyclops', 'VX-320 Cyclops', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 100 mph (160 km) maximum.', 'Flying: Via jet pack only; see the T-100 Eagle jet pack. Leaping: 15 feet (4.6 m) high/lengthwise; running leap adds 30 additional feet (9 m).', NULL, 'Average Height: 6 feet, 6 inches (2 m). Width: 3 feet, 6 inches (1 m). Length: 2 feet, 6 inches (0.7 m).', '500 lbs (225 kg)', 180, 2000000, 'Two to four million credits with all standard features and weapons. Fair availability.', 'A light, human-looking cyborg named for the single slot visor built into its head; removable gauntlets and forearm plates reveal human-looking hands and arms beneath.', 'Rifts World Book 5: Triax and the NGR p.101-103'),
('vx-340-slasher', 'VX-340 Slasher (Gold Type)', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 100 mph (160 km) in standard light infantry armor or 120 mph (192 km) in light espionage armor or no additional armor.', 'Flying: Via jet pack only; see the T-100 Eagle jet pack (half speed only, due to weight). Leaping: 25 feet (7.6 m) high/lengthwise; running leap adds 30 additional feet (9 m).', NULL, 'Average Height: 8 feet (2.4 m). Width: 4 feet (1.2 m). Length: 3 feet (0.9 m) body; 4 feet (1.2 m) including small launch tubes.', '1000 lbs (450 kg)', 180, 5000000, 'Five million credits with all standard features and weapons. Poor availability.', 'A full conversion cyborg known as the ''Gold Type'' with a monstrous head to intimidate opponents; favors mobility and free hands for explosives and assault weapons over heavy forearm weapons, often sent on espionage or seek-and-destroy missions.', 'Rifts World Book 5: Triax and the NGR p.103-104'),
('vx-370-stopper', 'VX-370 Stopper (Blue Type)', 'rifts', 'borg', 'One human volunteer.', NULL, 'Running: 100 mph (160 km) in the standard light infantry cyborg armor.', 'Flying: Via jet pack only; see the T-100 Eagle jet pack. Leaping: 15 feet (4.6 m) high/lengthwise; running leap adds 30 additional feet (9 m).', NULL, 'Average Height: 8 feet (2.4 m). Width: 4 feet (1.2 m). Length: 3 feet (0.9 m) (body itself).', '1400 lbs (630 kg)', 200, 5000000, 'Five million credits with all standard features and weapons. Poor availability.', 'A medium-heavy assault cyborg known as the ''Blue Type,'' strong, fast and agile with a monstrous head to intimidate opponents; equipped with a heavy particle beam weapon arm and a mini-machinegun.', 'Rifts World Book 5: Triax and the NGR p.105-106');

