VALUES
('x-2500-black-knight', 1, 'Ion Cannon (1)', '1D6 x 10 per blast', 1, '4000 feet (1200 m)', 'Equal to combined hand to hand attacks (usually 4-8)', 'Effectively unlimited', NULL, 'M.D.C. table lists this location as ''Ton Cannon (1; shoulder)''; Weapon Systems text calls it ''Ion Cannon'' - see flags'),
('x-2500-black-knight', 2, 'Forearm Lasers (2)', '3D6 M.D. per single blast or 6D6 M.D. per simultaneous double blast', 1, '4000 feet (1200 m)', 'Equal to combined hand to hand attacks (usually 4-8)', 'Effectively unlimited', NULL, NULL),
('x-2500-black-knight', 3, 'Forearm Vibro-Sword (2)', '5D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 to strike and +1 to parry in hand to hand combat', 'Weapon is eight feet long (2.4 m)'),
('x-2500-black-knight', 4, 'Electro-Mace (1)', '4D6 M.D. per strike (blunt); +10 M.D. if electrically charged; or up to three electrical blasts of 1D4x10 M.D. each', 1, 'Electrical discharge max 1000 feet (305 m)', 'Combined hand to hand attacks (usually 4-8); electrical blast max 3/melee', 'Effectively unlimited', NULL, NULL),
('x-2500-black-knight', 5, 'Lower Leg Mini-Missile Launchers (4)', 'Varies with missile type; standard armor piercing (1D4x10 M.D.) or plasma (1D6x10)', 1, 'Usually about a mile', 'One at a time or volleys of 2, 3 or 4', '56 total; 14 in each launcher', NULL, NULL),
('x-2500-black-knight', 6, 'Grenade Tubes (8)', 'Varies with type', 0, '500 feet (152 m)', 'One at a time or volleys of 2 or 4', '32 total; 4 in each launch tube. Typically 10 smoke, 22 tear gas (or 10, 14 and 8 fragmentation)', NULL, NULL),
('x-2500-black-knight', 7, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', NULL, NULL, NULL, 'Restrained Punch 1D6 M.D.; Full Strength Punch 3D6 M.D.; Power Punch 6D6 M.D.(2 atk); Vibro-Blade 5D6; Electro-Mace 4D6(uncharged)/4D6+10(charged); Crush/Pry/Tear 2D6; Kick 3D6; Leap Kick 5D6(2atk); Body Flip/Throw 1D6; Body Block/Ram 2D6; Stomp 2D4 vs targets <=10ft. Bonuses: +2 strike,+4 parry,+3 dodge,+2 roll w/impact,+2 pull punch,+2 actions lvl1,+1 add''l at 3,6,10,14.'),
('x-2700-dragonwing', 1, 'Weapon Arms - Laser Cannon', '1D4 x 10 per blast; double if both weapon arms synchronized on same target (counts as one melee action)', 1, '6000 feet (1828 m)', 'Equal to combined hand to hand attacks (usually 4-8)', 'Effectively unlimited', '+1 to strike, +1 to parry and dodge', 'Special Feature: own laser targeting and short-range radar tracking (3 mile/4.8 km radar range)'),
('x-2700-dragonwing', 1, 'Weapon Arms - Ion Cannon', '1D4 x 10 M.D. per blast; double if synchronized on same target; quadruple if both ion cannons and both laser cannons synchronous at close range (2000 ft/610 m), counts as two melee actions', 1, '2000 feet (610 m)', 'Equal to combined hand to hand attacks (usually 4-8)', 'Effectively unlimited', '+1 to strike, +1 to parry and dodge', NULL),
('x-2700-dragonwing', 2, 'Forward Rapid-Fire Machineguns (2)', '2D4 M.D. per burst of 20 rounds or 4D4 M.D. per simultaneous double burst (40 rounds); low radiation U-Rounds 2D6 M.D. or 4D6 M.D. (double) to supernatural monsters', 1, '4000 feet (1200 m)', 'Equal to combined hand to hand attacks (usually 4-8)', '6000 rounds total; 3000 per machinegun (300 bursts, 150 per gun)', NULL, NULL),
('x-2700-dragonwing', 3, 'Concealed Chest Missiles', 'Varies with missile type; standard armor piercing (2D4x10 M.D.; multi-warhead) or plasma (2D6x10)', 1, '40+ miles (64+ km)', 'One at a time or volleys of two or four', '12 missiles', NULL, NULL),
('x-2700-dragonwing', 4, 'Tail Swivel Laser Mounts (2)', '3D6 M.D. per single blast or 6D6 from simultaneous blast from both', 1, '6000 feet (1828 m)', 'Equal to combined hand to hand attacks (usually 4-8)', 'Effectively unlimited', NULL, NULL),
('x-2700-dragonwing', 5, 'Optional Electro-Mace (1)', '4D6 M.D. per strike (blunt); +10 M.D. if charged; or up to three electrical blasts of 1D4x10 M.D. each', 1, 'Electrical blast max 1000 feet (305 m)', 'Combined hand to hand attacks (usually 4-8); electrical blast max 3/melee', 'Effectively unlimited', NULL, 'Identical to the one used by the Black Knight'),
('x-2700-dragonwing', 6, 'Optional: Slammer Concussion Bombs', '1D4 x 10 M.D. to entire 90 foot (27.4 m) diameter blast radius; knockdown (01-88%) and stun (01-65%) as per Slammer missiles', 1, '6000 feet (1830 m)', 'One at a time or clusters of two to ten', '20 total', NULL, NULL),
('x-2700-dragonwing', 7, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', NULL, NULL, NULL, 'Restrained Punch 1D6; Full Strength Punch 3D6; Power Punch 6D6(2atk); Crush/Pry/Tear 2D6; Kick 3D6; Leap Kick 5D6(2atk); Thruster Blast from Feet 2D6; Body Flip/Throw 1D6; Body Block/Ram 2D6(running); Flying Body Block/Ram 5D6@100mph,1D6x10@200mph,2D4x10@300mph,4D4x10@500mph,4D6x10@Mach1,1D4x100@Mach2 (half damage self at Mach speed); Electro-Mace 4D6(uncharged)/4D6+10(charged); Stomp 2D4 vs targets <=10ft. Bonuses: +2 strike,+4 parry,+3 dodge ground/+5 dodge flying Mach1+,+2 roll w/impact,+2 pull punch,+2 actions lvl1,+1 add''l at 3,6,10,14.'),
('x-5000-devastator', 1, 'TX-5000 Super Laser Cannon (1)', '1D6 x 10 M.D. per single full power blast, or 4D6 M.D. low power blasts', 1, '8000 feet (2438 m)', 'Equal to combined hand to hand attacks (usually 4-8)', '50 full strength blasts; low power blasts fired indefinitely', '+2 to strike', 'Special Feature: Independent and coordinated targeting'),
('x-5000-devastator', 2, 'TX-5001 Super Ion Cannon (1)', '2D4 x 10 M.D. per blast', 1, '4000 feet (1200 m)', 'Equal to combined hand to hand attacks (usually 4-8)', 'Effectively unlimited', '+1 to strike', 'Special Feature: Independent and coordinated targeting'),
('x-5000-devastator', 3, 'Long-Range Missile Launchers (4)', 'Varies with missile type; standard proton torpedoes (4D6x10 M.D.), nuclear multi-warhead (4D6x10 M.D.) or heavy plasma (3D6x10 M.D.); all smart bombs, +5 to strike', 1, 'Usually about 1000+ miles (1640+ km)', 'One at a time or volleys of two or four', '32 missiles total; 8 in each launcher', NULL, NULL),
('x-5000-devastator', 4, 'Medium Range Missile Launchers (2)', 'Varies with missile type; standard armor piercing (2D4x10 M.D.; multi-warhead) or plasma (2D6x10); all missiles +3 to strike', 1, 'Usually about 40+ miles (64+ km)', 'One at a time or volleys of two or four', '16 missiles; 8 in each launcher', NULL, NULL),
('x-5000-devastator', 5, 'Mini-Missile Launchers (2)', 'Varies with missile type; standard armor piercing (1D4x10 M.D.) or plasma (1D6x10)', 1, 'Usually about a mile', 'One at a time or volleys of 2, 3 or 4', '60 total; 30 in each launcher compartment', NULL, NULL),
('x-5000-devastator', 6, 'Ion Belly Gun Turret', '4D6 M.D. per single blast or 1D4 x 10 per dual simultaneous blast', 1, '4000 feet (1200 m)', 'Equal to combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Turret can fire one gun or both simultaneously; entire upper torso rotates 360 degrees'),
('x-5000-devastator', 7, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', NULL, NULL, NULL, 'Restrained Punch 2D6; Full Strength Punch 1D6x10; Power Punch 2D6x10(2atk); Crush/Pry/Tear 1D6x10; Kick 1D6x10; Leap Kick Not possible; Body Flip/Throw 4D6; Body Block/Ram 1D6x10; Stomp 6D6 vs targets <=15ft. Bonuses: +1 strike(plus weapon bonuses),+1 parry,No dodge,No roll w/impact,No pull punch,+1 add''l action at levels 2,6,10,14.'),
('dv-12-dyna-bot', 1, 'TX-50 Rail Gun (1 or 2)', 'A full damage burst fires 20 rounds and inflicts 5D6 M.D.; a single round does 1D4 M.D.', 1, '4000 feet (1200 m)', 'Equal to the bot''s hand to hand attacks (usually 6)', 'Short clip 200 rounds (10 bursts), light drum 600 rounds (30 bursts), or heavy belt-feed drum 2000 rounds (100 bursts)', NULL, NULL),
('dv-12-dyna-bot', 2, 'Laser finger guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if both fingers fire simultaneously on an aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('dv-12-dyna-bot', 3, 'Concealed Particle Beam Rod (light)', '5D6+6 M.D.', 1, '1600 feet (488 m)', 'Equal to the number of hand to hand melee attacks', 'Effectively unlimited', NULL, 'Concealed in one of the legs, powered by the bot''s nuclear battery; weighs 15 lbs (7 kg)'),
('dv-12-dyna-bot', 4, 'Chemical spray from the mouth', NULL, 0, NULL, NULL, 'Total of 60 doses', NULL, 'Releases toxic mists (same as bionics, Rifts RPG p.240); combat models usually equipped with tranquilizer/sleep spray or tear gas'),
('dv-12-dyna-bot', 5, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Six (6) attacks per melee', NULL, NULL, 'Restrained Punch 2D6+25 S.D.C.; Full Strength Punch 2D6 M.D.; Power Punch 4D6+4 M.D.; Head Butt 1D6 M.D.; Kick 1D8 M.D.; Jump Kick/Leap Attack double damage (2D8 M.D.); Judo throw/flip 1D4 M.D.; critical on natural 19-20. Extensive combat bonuses from programming/sensors listed in text; impervious to poison, gas, biological agents, psionic/magic mind control, charms, bio-manipulation and S.D.C. attacks.'),
('dv-15-sentry-bot', 1, 'TX-30 Ion Pulse Rifle', '2D6 M.D. single shot or 6D6 M.D. pulse mode (3 simultaneous blasts at a single target)', 1, '2000 feet (610 m)', 'Equal to the bot''s hand to hand attacks (usually 6)', '40 shot short E-clip or 50 shot long E-clip', NULL, 'Weighs 7 lbs (3 kg); any handheld weapon can be used in its place'),
('dv-15-sentry-bot', 2, 'DV Laser finger guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if simultaneous aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('dv-15-sentry-bot', 3, 'DV Concealed Particle Beam Rod (light)', '5D6+6 M.D.', 1, '1600 feet (488 m)', 'Equal to the number of hand to hand melee attacks', 'Effectively unlimited', NULL, 'Concealed in one of the legs; weighs 15 lbs (7 kg)'),
('dv-15-sentry-bot', 4, 'Chemical spray from the mouth', NULL, 0, NULL, NULL, 'Total of 60 doses', NULL, 'Sentry models usually equipped with tranquilizer/sleep spray or tear gas'),
('dv-15-sentry-bot', 5, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Six (6) attacks per melee', NULL, NULL, 'Restrained Punch 2D6+25 S.D.C.; Full Strength Punch 2D6 M.D.; Power Punch 4D6+4 M.D.(2atk); Head Butt 1D6 M.D.; Kick 1D8 M.D.; Jump Kick/Leap Attack double damage (2D8 M.D.); Judo throw/flip 1D4 M.D.; critical on natural 19-20. Impervious to poison, gas, biological agents, psionic/magic mind control, charms, bio-manipulation and S.D.C. attacks.'),
('dv-15-sentry-bot', 6, 'TX-50 Rail Gun (1, optional)', 'See DV-12 Dyna-bot for complete details', 1, NULL, NULL, NULL, NULL, 'Optional accessory for the DV-15'),
('dv-15-sentry-bot', 8, 'Hand Grenades', 'Varies; see the X-60 Flanker for grenade descriptions', 0, NULL, NULL, 'Two to eight tear gas/stun or smoke grenades', NULL, 'Provided to impair/confuse attackers or escaping prisoners'),
('dv-40-hunter-killer-drone', 1, 'TX-41 Laser Pulse Rifle (1)', '3D6 M.D. per single shot or 1D6 x 10 M.D. per rapid fire pulse of 3 shots (nearly simultaneous)', 1, '4000 feet (1200 m)', 'Equal to the total number of hand to hand attacks', '100; giant energy clip in front of gun, or cable-connected to bot''s energy supply for effectively indefinite payload (cable can be cut); second E-clip concealed in left leg', NULL, 'Variable frequency laser with 12 light frequencies, changeable by touch or voice command; setting 7 counters the USA-10 Glitter Boy'),
('dv-40-hunter-killer-drone', 2, 'DV-40 Grenade Launcher (1)', 'Varies; typically fragmentation (2D6 M.D. to 20 ft/6 m radius), plasma (5D6 M.D. to 12 ft/3.6 m diameter), smoke (no damage), or riot control/tear gas/stun', 1, '300 feet (91.5 m)', 'One at a time or volleys of two or three fired in rapid succession', '48 total; typically 4 smoke, 4 tear gas, 20 plasma, 20 fragmentation', NULL, NULL),
('dv-40-hunter-killer-drone', 3, 'DV-40 Concealed Particle Beam Rod (1)', '5D6+6 M.D.', 1, '1600 feet (488 m)', 'Equal to the number of hand to hand melee attacks', 'Effectively unlimited', NULL, 'Concealed in the right arm; weighs 15 lbs (7 kg)'),
('dv-40-hunter-killer-drone', 4, 'DV-40 Laser finger guns (2)', 'Two settings: 2D6 M.D. or 3D6 M.D. per finger; double damage if both fingers fire simultaneously on an aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', NULL, NULL),
('dv-40-hunter-killer-drone', 5, 'Forearm Vibro-Sword (1)', '3D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 to strike and +1 to parry in hand to hand combat', 'Located in the right forearm; three feet long (0.9 m)'),
('dv-40-hunter-killer-drone', 6, 'Diamond Tipped Chainsaw (1)', '3D6 M.D. per melee attack or 3D6 x 6 M.D. per one full melee (15 seconds) of cutting', 1, 'Touch', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', NULL, 'Located on the left arm; can cut mega-damage steel, concrete and rock'),
('dv-40-hunter-killer-drone', 7, 'Flamethrowers (2)', '1D4 M.D. per single blast or 2D4 per simultaneous double blast of napalm-like fire; 01-90% chance of igniting combustibles, +1D4 M.D./melee burning for 2D4 minutes', 1, '200 feet (61 m)', 'Equal to number of hand to hand attacks (usually 6)', '50 blasts total, 25 from each', NULL, 'Mounted on the rib cage area, 360-degree rotation'),
('dv-40-hunter-killer-drone', 9, 'Optional TX-843P Interchangeable Particle Beam Cannon (1)', '2D4 x 10 M.D. per single blast', 1, '3000 feet (914 m)', 'Equal to number of hand to hand attacks (usually 6)', 'Effectively unlimited', NULL, 'Mounted on shoulders via TX-481 universal mounts (as X-535 Jager); weighs three tons with own energy supply; reduces speed/combat bonuses by 25%'),
('dv-40-hunter-killer-drone', 10, 'Optional TX-884I Interchangeable Ion Cannon & Missile Launcher (1)', 'Ion Cannon: 1D6 x 10 per blast. Missiles: varies with type (armor piercing 2D4x10, plasma 2D6x10)', 1, 'Cannon 4000 feet (1200 m); Missiles 40+ miles (64+ km)', 'Cannon equal to hand to hand attacks (usually 6); missiles one at a time or volleys of two or four', 'Cannon effectively unlimited; missiles 12 total, 6 per launcher', '+1 to strike (cannon)', 'Reduces robot''s speed by 50%; overall weight 6 tons'),
('dv-40-hunter-killer-drone', 11, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Six (6) attacks per melee', NULL, NULL, 'Restrained Punch 1D6 M.D.C.; Full Strength Punch 3D6 M.D.; Power Punch 5D6 M.D.(2atk); Chainsaw 3D6; Vibro-sword 3D6; Head Butt 1D6; Kick 2D6; Body Block 2D6(+1D6 running); Jump Kick/Leap Attack 4D6(2atk); Judo throw/flip 1D6; critical on natural 19-20.'),
('eir-10-gargoyle-drone', 1, 'Laser Eyes (2)', '2D6 M.D. per single eye blast or 4D6 M.D. per double blast (both eyes simultaneously, counts as one melee action)', 1, '2000 feet (610 m)', 'Equal to the bot''s total number of hand to hand attacks per melee', 'Effectively unlimited', '+1 to strike', '180 degree rotation/arc of fire - look and shoot'),
('eir-10-gargoyle-drone', 2, 'Laser Finger Guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if simultaneous aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('eir-10-gargoyle-drone', 3, 'Concealed Vibro-blades in the Forearms (2)', '4D6 M.D. each', 1, 'Hand to hand', 'Equal to the number of hand to hand melee attacks', NULL, NULL, 'Used only for assassination or when the bot has no other course of defense'),
('eir-10-gargoyle-drone', 4, 'Chemical spray from the mouth', NULL, 0, NULL, NULL, 'Total of 60 doses', NULL, 'Combat models usually equipped with tranquilizer/sleep spray or tear gas'),
('eir-10-gargoyle-drone', 5, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Seven (7) attacks per melee', NULL, NULL, 'Restrained Punch 3D6+25 S.D.C.; Full Strength Punch 4D6 M.D.; Power Punch 1D4x10 M.D.; Tail Strike 2D6; Bite 2D4; Head Butt 1D6; Kick 4D6; Jump Kick/Leap Attack 1D4x10; Judo throw/flip 1D6; critical on natural 19-20. Tail is prehensile and can pick up/carry things.'),
('eir-15-gargoyle-manned-robot', 1, 'Weapon Systems (identical to EIR-10 drone)', NULL, 1, NULL, NULL, NULL, NULL, 'Book states: ''Identical to the drone, only operated by the pilot.'' An internal computer and language translator lets the pilot understand and reply in the appropriate monster language. Attacks Per Melee: pilot''s hand to hand plus one additional attack/action at levels 1, 3, 5, 8 and 12 of the pilot''s experience. See EIR-10 Gargoyle Drone for the itemized weapon stats (laser eyes, laser finger guns, concealed forearm vibro-blades, chemical spray, hand to hand).'),
('eir-20-gurgoyle-drone', 1, 'Laser Eyes (2)', '2D6 M.D. per single eye blast or 4D6 M.D. per double blast (both eyes simultaneously, counts as one melee action)', 1, '2000 feet (610 m)', 'Equal to the bot''s total number of hand to hand attacks per melee', 'Effectively unlimited', '+1 to strike', '180 degree rotation/arc of fire - look and shoot'),
('eir-20-gurgoyle-drone', 2, 'Laser Finger Guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if simultaneous aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('eir-20-gurgoyle-drone', 3, 'DV-40 Concealed Particle Beam Rod (1)', '5D6+6 M.D.', 1, '1600 feet (488 m)', 'Equal to the number of hand to hand melee attacks', 'Effectively unlimited', NULL, 'Concealed in the right leg'),
('eir-20-gurgoyle-drone', 4, 'Chemical spray from the mouth', NULL, 0, NULL, NULL, 'Total of 60 doses', NULL, 'Combat models usually equipped with tranquilizer/sleep spray or tear gas'),
('eir-20-gurgoyle-drone', 5, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Seven (7) attacks per melee', NULL, NULL, 'Restrained Punch 3D6+15 S.D.C.; Full Strength Punch 3D6 M.D.; Power Punch 1D4x10 M.D.; Tail Strike 2D6; Bite 2D4; Head Butt 1D6; Kick 4D6; Jump Kick/Leap Attack 1D4x10; Judo throw/flip 1D6; critical on natural 19-20. Tail is prehensile.'),
('eir-30-gargoylite-drone', 1, 'Laser Finger Guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if simultaneous aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('eir-30-gargoylite-drone', 2, 'Chemical spray from the mouth', NULL, 0, NULL, NULL, 'Total of 15 doses', NULL, 'Combat models usually equipped with tranquilizer/sleep spray or tear gas'),
('eir-30-gargoylite-drone', 3, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Five (5) attacks per melee', NULL, NULL, 'Restrained Punch 1D6+5 S.D.C.; Full Strength Punch 1D4 M.D.; Power Punch 2D4 M.D.; Tail Strike not applicable (too small); Bite 1 M.D.; Head Butt 4D6+5 S.D.C.; Kick 1D4 M.D.; Jump Kick/Leap Attack 1D6 M.D. Small size makes it a poor unarmed combatant; ideally uses a human-size energy handgun.'),
('eir-50-gurgoyle-android', 1, 'Laser Finger Guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if simultaneous aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', 'One finger on each hand is artificial and contains the laser'),
('eir-50-gurgoyle-android', 2, 'Garrote Wrist Wire (1)', 'Equal to a power punch: 6D6 M.D. per melee action (every time it is pulled tighter)', 1, 'Hand to hand', NULL, NULL, NULL, 'A thin, giant-sized, thick wire hidden in a cybernetic housing, used for assassination, usually from behind'),
('eir-50-gurgoyle-android', 3, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Seven (7) attacks per melee', NULL, NULL, 'Restrained Punch 3D6+15 S.D.C.; Full Strength Punch 3D6 M.D.; Power Punch 6D6 M.D.; Tail Strike 2D6; Bite 1D6; Head Butt 1D4(not advisable); Kick 3D6; Jump Kick/Leap Attack 6D6; Judo throw/flip 1D6; critical on natural 19-20. Tail is prehensile.'),
('eic-100-gurgoyle-cyborg', 1, 'Laser Eyes (2)', '2D6 M.D. per single eye blast or 4D6 M.D. per double blast (both eyes simultaneously, counts as one melee action)', 1, '2000 feet (610 m)', 'Equal to the borg''s total number of hand to hand attacks per melee', 'Effectively unlimited', '+1 to strike', '180 degree rotation/arc of fire - look and shoot'),
('eic-100-gurgoyle-cyborg', 1, 'Particle Beam Eyes (2)', '5D6+6 M.D. per single eye blast or 1D6 x 10+12 M.D. per double blast (both eyes simultaneously, counts as one melee action)', 1, '800 feet (245 m)', 'Equal to the character''s total number of hand to hand attacks per melee', 'Effectively unlimited', '+1 to strike', 'Exclusive to the NGR military - an over-sized head like the gurgoyle''s is needed; more damage but shorter range than the laser variant'),
('eic-100-gurgoyle-cyborg', 2, 'Laser Finger Guns (2)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D. per finger; double damage if simultaneous aimed shot', 1, '2000 feet (610 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('eic-100-gurgoyle-cyborg', 3, 'VX-40 Concealed Particle Beam Rod (1)', '5D6+6 M.D.', 1, '1600 feet (488 m)', 'Equal to the number of hand to hand melee attacks', 'Effectively unlimited', NULL, 'Concealed in the right leg'),
('eic-100-gurgoyle-cyborg', 4, 'Chemical spray from the mouth', NULL, 0, NULL, NULL, 'Total of 15 doses', NULL, 'Combat models usually equipped with tranquilizer/sleep spray or tear gas'),
('eic-100-gurgoyle-cyborg', 5, 'Retractable Vibro-Blade', '2D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, 'A large vibro-sword concealed in the right or left arm'),
('eic-100-gurgoyle-cyborg', 6, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Character''s hand to hand combat skill/experience, plus one additional attack from heightened reflexes and one from the prehensile tail', NULL, NULL, 'Restrained Punch 1D6+15 S.D.C.; Full Strength Punch 1D4 M.D.; Power Punch 2D6 M.D.; Tail Strike 1D6; Bite 6D6 S.D.C.; Head Butt 1D4; Kick 1D4; Jump Kick/Leap Attack 2D4; Judo throw/flip 6D6 S.D.C. Bonuses: +1 initiative, +1 pull punch, +1 roll w/impact, +2 save vs horror factor.'),
('vx-300-striker', 1, 'VX-300 Multiple Grenade Launcher System', 'Special VX-300 fragmentation grenades: 3D6 M.D. to a 50 ft (15 m) radius; or plasma 5D6 M.D. to a 12 ft (3.6 m) radius; or tear gas/stun or smoke', 1, '300 feet (91.5 m)', 'One at a time or volleys of two, three or four', '25 total; seven in each shoulder, five on the forearm, six in the belly. Typical combo: 3 stun/tear gas, 8 plasma, 14 fragmentation', NULL, NULL),
('vx-300-striker', 2, 'VX-300 Rail Gun-Arm (1, standard issue)', 'A full damage burst fires 20 rounds and inflicts 4D6 M.D.; a single round does two M.D.; DU-rounds 5D6 M.D.; U-rounds 5D6 M.D. (also diminishes healing in supernatural beings)', 1, '4000 feet (1200 m)', 'Equal to the character''s hand to hand attacks per melee round (usually 4 to 6)', 'Short clip 200 rounds (10 bursts) or 2000 round drum (100 bursts)', '+1 to strike', 'Built into the borg as part of the left forearm; can be replaced with a mechanical human-like arm or other weapon arm; own laser targeting/distancing, telescopic sight and nightvision scope, range 6000 ft/1828 m'),
('vx-300-striker', 3, 'Laser Finger Gun (1)', 'Three settings: 1D6 x 10 S.D.C., or 1D6 M.D., or 2D6 M.D.', 1, '500 feet (152 m)', 'Equal to the total number of hand to hand attacks', 'Effectively unlimited', '+1 to strike', NULL),
('vx-300-striker', 4, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Character''s hand to hand combat skill/experience plus one additional attack from heightened reflexes', NULL, '+3 to strike, parry and dodge from P.P. 21', 'Restrained Punch 1D6+9 S.D.C.; Full Strength Punch 3D6+9 S.D.C.; Power Punch 1D4 M.D.(2atk); Head Butt 2D6 S.D.C.; Kick 3D6+9 S.D.C.; Jump Kick/Leap Attack 1D6 M.D.(2atk); Judo throw/flip 2D6 S.D.C. Combat Bonuses: +2 initiative, +2 pull punch, +2 roll w/impact, +1 save vs horror factor.'),
('vx-320-cyclops', 1, 'VX-320 Multiple Grenade Launcher System', 'Special fragmentation grenades: 3D6 M.D. to a 50 ft (30.5 m as printed) radius; or plasma 5D6 M.D. to a 12 ft (3.6 m) radius; or tear gas/stun or smoke', 1, '300 feet (91.5 m)', 'One at a time or volleys of two, three or four', '25 total; seven in each shoulder, five on the forearm, six in the belly. Typical combo: 10 plasma, 3 smoke, 12 fragmentation', NULL, 'Radius given as ''50 feet (30.5 m)'' in the text, which is an internally inconsistent conversion (50 ft is ~15.2 m) - transcribed as printed, see flags'),
('vx-320-cyclops', 2, 'VX-320 Wide Beam Ion Disrupter (1)', '2D6 M.D. per blast to everything within a 10 foot (3 m) diameter; 4D6 M.D. at point-blank range (within 4 feet/1.2 m)', 1, '60 feet (18.3 m)', 'Maximum of twice per melee round; each blast counts as one melee action/attack', 'Effectively unlimited; patched into the borg''s power supply', NULL, 'Fires an energy pulse/sphere that expands to strike multiple close targets'),
('vx-320-cyclops', 3, 'Laser Forearm Gun (1)', '2D6 M.D. per blast', 1, '2000 feet (609 m)', 'Equal to the total number of hand to hand attacks', '20 shots per E-clip', NULL, 'Right arm; no penalty or bonus to strike (light design)'),
('vx-320-cyclops', 4, 'Ion Forearm Gun (1)', '3D6 M.D. per blast', 1, '1000 feet (305 m)', 'Equal to the total number of hand to hand attacks', '20 shots per E-clip', NULL, 'Left arm; no penalty or bonus to strike (light design)'),
('vx-320-cyclops', 5, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Character''s hand to hand combat skill/experience plus one additional attack from heightened reflexes', NULL, '+3 to strike, parry and dodge from P.P. 21', 'Restrained Punch 1D6+9 S.D.C.; Full Strength Punch 3D6+9 S.D.C.; Power Punch 1D4 M.D.; Head Butt 2D6 S.D.C.; Kick 3D6+9 S.D.C.; Jump Kick/Leap Attack 1D6 M.D.; Judo throw/flip 2D6 S.D.C. Combat Bonuses: +2 initiative, +2 pull punch, +2 roll w/impact, +1 save vs horror factor.'),
('vx-340-slasher', 1, 'Concealed Vibro-Blades (2)', '2D6 M.D. per strike', 1, 'Hand to hand', 'Total hand to hand melee actions', NULL, NULL, 'Each forearm has a vibro-sword that extends/retracts at will; borg''s P.P. 24 gives +5 strike/parry bonus not including W.P. Sword bonuses'),
('vx-340-slasher', 2, 'VX-340 Mini-Missile Tube Launchers (4)', 'Varies with missile type; standard armor piercing (1D4x10 M.D.) or plasma (1D6x10); fragmentation seldom used', 1, 'Usually about a mile', 'One at a time or volleys of two or three', 'Four total; one in each tube', NULL, NULL),
('vx-340-slasher', 3, 'Concealed Leg Laser Rod (1)', '3D6 M.D. per blast', 1, '3000 feet (914 m)', 'Equal to the total number of hand to hand attacks', '20 shots per E-clip', NULL, 'Right or left hip; release, point and shoot'),
('vx-340-slasher', 4, 'TX-500 or TX-250 Triax Borg Rail Gun (1; standard issue, pick one)', 'Full burst 30 rounds 6D6 M.D.; half burst 15 rounds 3D6 M.D.; one round 1D4 M.D.; DU rounds add 2D6 M.D. (full burst) or 1D6 M.D. (half burst)', 1, '4000 feet (1200 m)', 'One burst per hand to hand melee action/attack', 'Heavy ammo-drum 1170 rounds (39 full bursts); light drum/belt 390 rounds (13 full bursts); mini-clip 90 rounds (3 full bursts)', '+1 to strike', 'Weighs 80 lbs (36.3 kg) gun, 50 lbs (22.7 kg) power pack; 85,000 credits market cost, Fair availability; telescopic, nightvision scope and laser targeting'),
('vx-340-slasher', 5, 'Concealed Weapon Compartments', 'Pair of vibro-knives (1D6 M.D.) and two to eight hand grenades (any type)', 1, NULL, NULL, NULL, NULL, 'Two concealed compartments in the chest'),
('vx-340-slasher', 6, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Character''s hand to hand combat skill/experience plus one additional attack from heightened reflexes', NULL, '+5 to strike, parry and dodge from P.P. 24', 'Restrained Punch 1D6+12 S.D.C.; Full Strength Punch 3D6+12 S.D.C.; Power Punch 1D4 M.D.(2atk); Head Butt 2D6 S.D.C.; Kick 4D6+12 S.D.C.; Jump Kick/Leap Attack 2D4 M.D.(2atk); Judo throw/flip 3D6 S.D.C.; Full Speed Ram/Body Block 1D4 M.D.(2atk). Combat Bonuses: +2 initiative, +3 pull punch, +1 roll w/impact, +1 save vs horror factor.'),
('vx-370-stopper', 1, 'VX-370 Particle Beam Weapon Arm (1, standard issue)', '6D6+6 M.D. per blast', 1, '1000 feet (305 m)', 'Equal to the character''s total number of hand to hand attacks per melee', '50 shots; independent regenerating power supply recharges 10 blasts/hour, or a standard energy rifle E-clip can be inserted for 10 blasts/clip', NULL, 'Penalty: -1 to strike and parry; the arm is heavy and a bit awkward. Right or left forearm.'),
('vx-370-stopper', 2, 'VX-370 Mini-machinegun (1, standard issue)', 'A full damage burst fires 30 rounds and inflicts 2D4 M.D.', 1, '2000 feet (609 m)', 'Equal to the character''s hand to hand attacks per melee round (usually 4 to 6)', '2000 round drum, capable of firing 66 full bursts (30 rounds each)', NULL, 'Penalty: -1 to strike and parry; the arm is heavy and a bit awkward. Gun-arm 25 lbs (11 kg), ammo-drum 40 lbs (18 kg)'),
('vx-370-stopper', 3, 'Concealed Leg Laser Rod (1)', '3D6 M.D. per blast', 1, '3000 feet (914 m)', 'Equal to the total number of hand to hand attacks', '20 shots per E-clip', NULL, 'Left hip; release, point and shoot'),
('vx-370-stopper', 4, 'Hand to Hand Combat', NULL, 1, 'Hand to hand', 'Character''s hand to hand combat skill/experience plus one additional attack from heightened reflexes', NULL, '+4 to strike, parry and dodge from P.P. 22', 'Restrained Punch 1D6+12 S.D.C.; Full Strength Punch 3D6+12 S.D.C.; Power Punch 1D4 M.D.(2atk); Head Butt 2D6 S.D.C.; Kick 4D6+12 S.D.C.; Jump Kick/Leap Attack 2D4 M.D.(2atk); Judo throw/flip 3D6 S.D.C.; Full Speed Ram/Body Block 1D4 M.D.(2atk). Combat Bonuses: +1 initiative, +1 pull punch, +1 save vs horror factor.');

-- Read the result back rather than trusting the exit code. INSERT OR IGNORE
-- is silent on collision, so what matters is how many rows are THERE.
SELECT 'vessels from p071-105' AS assertion,
       count(*) AS got, 16 AS want
  FROM vehicles WHERE slug IN ('x-2500-black-knight', 'x-2700-dragonwing', 'x-5000-devastator', 'dv-12-dyna-bot', 'dv-15-sentry-bot', 'dv-40-hunter-killer-drone', 'eir-10-gargoyle-drone', 'eir-15-gargoyle-manned-robot', 'eir-20-gurgoyle-drone', 'eir-30-gargoylite-drone', 'eir-50-gurgoyle-android', 'eic-100-gurgoyle-cyborg', 'vx-300-striker', 'vx-320-cyclops', 'vx-340-slasher', 'vx-370-stopper');

SELECT 'their M.D.C.-by-location rows' AS assertion,
       count(*) AS got, 159 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('x-2500-black-knight', 'x-2700-dragonwing', 'x-5000-devastator', 'dv-12-dyna-bot', 'dv-15-sentry-bot', 'dv-40-hunter-killer-drone', 'eir-10-gargoyle-drone', 'eir-15-gargoyle-manned-robot', 'eir-20-gurgoyle-drone', 'eir-30-gargoylite-drone', 'eir-50-gurgoyle-android', 'eic-100-gurgoyle-cyborg', 'vx-300-striker', 'vx-320-cyclops', 'vx-340-slasher', 'vx-370-stopper');

SELECT 'their weapon systems' AS assertion,
       count(*) AS got, 87 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('x-2500-black-knight', 'x-2700-dragonwing', 'x-5000-devastator', 'dv-12-dyna-bot', 'dv-15-sentry-bot', 'dv-40-hunter-killer-drone', 'eir-10-gargoyle-drone', 'eir-15-gargoyle-manned-robot', 'eir-20-gurgoyle-drone', 'eir-30-gargoylite-drone', 'eir-50-gurgoyle-android', 'eic-100-gurgoyle-cyborg', 'vx-300-striker', 'vx-320-cyclops', 'vx-340-slasher', 'vx-370-stopper');

SELECT 'every location row points at a vessel that exists' AS assertion,
       count(*) AS got, 0 AS want
  FROM vehicle_locations l
  LEFT JOIN vehicles v ON v.slug = l.vehicle_slug
  WHERE v.slug IS NULL;

